const YieldReasonCompacted YieldReason = "compacted"
const YieldReasonEffectBoundary YieldReason = "effect_boundary"
const YieldReasonGoalContinue YieldReason = "goal_continue"
const YieldReasonIterationCap YieldReason = "iteration_cap"
const YieldReasonMailbox YieldReason = "mailbox"
const YieldReasonWallCap YieldReason = "wall_cap"

var enumValues_YieldReason = []interface{}{
	"iteration_cap",
	"wall_cap",
	"effect_boundary",
	"budget_soft",
	"cancel",
	"goal_continue",
	"mailbox",
	"compacted",
}

// UnmarshalJSON implements json.Unmarshaler.
func (j *YieldReason) UnmarshalJSON(value []byte) error {
	var v string
	if err := json.Unmarshal(value, &v); err != nil {
		return err
	}
	var ok bool
	for _, expected := range enumValues_YieldReason {
		if reflect.DeepEqual(v, expected) {
			ok = true
			break
		}
	}
	if !ok {
		return fmt.Errorf("invalid value (expected one of %#v): %#v", enumValues_YieldReason, v)
	}
	*j = YieldReason(v)
	return nil
}
